 async function importFile(file:File){await run(async()=>{const matrix=file.name.toLowerCase().endsWith('.csv')?readCsv(await file.text()):await readXlsx(file);const headers=matrix[0]?.map(v=>String(v).replace(/^\uFEFF/,'').trim().toLowerCase());const required=['nomor pegawai','nama','jabatan','unit kerja','kriteria','nama penerima','nomor rekening'];if(!headers||required.some(x=>!headers.includes(x)))throw new Error('Gunakan template impor agar nama kolom sesuai.');const items=matrix.slice(1).filter(r=>r.some(v=>String(v).trim())).map((r,i)=>{const v=(key:string)=>r[headers.indexOf(key)]??'';if(typeof v('nomor pegawai')==='number'||typeof v('nomor rekening')==='number')throw new Error(`Baris ${i+2}: nomor pegawai dan rekening harus disimpan sebagai TEKS di Excel, agar nol awal tidak hilang.`);const e={...blankEmployee(),employeeNo:String(v('nomor pegawai')).trim(),name:String(v('nama')).trim(),position:String(v('jabatan')).trim(),unit:String(v('unit kerja')).trim(),criterion:Number(v('kriteria')),creditName:String(v('nama penerima')).trim(),bankAccount:String(v('nomor rekening')).trim()};if(!e.employeeNo||!e.name||!e.position||!e.unit||!e.creditName||!/^\d+$/.test(e.bankAccount)||!Number.isInteger(e.criterion)||e.criterion<1||e.criterion>10)throw new Error(`Baris ${i+2}: data tidak lengkap, kriteria di luar 1–10, atau rekening tidak valid.`);return e;});if(!items.length||items.length>2000)throw new Error('Impor harus berisi 1–2.000 pegawai.');const seen=new Set(boot!.employees.map(e=>e.employeeNo));for(const e of items){if(seen.has(e.employeeNo))throw new Error('Nomor pegawai ganda/sudah ada: '+e.employeeNo);seen.add(e.employeeNo);}setImportRows(items);});}

